# inspect each connected component and count of 9
from collections import deque
h,w=len(test),len(test[0]); seen=set(); objs=[]
for r in range(h):
 for c in range(w):
  if test[r][c] and (r,c) not in seen:
   q=deque([(r,c)]);seen.add((r,c)); cells=[]
   while q:
    y,x=q.popleft();cells.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     yy,xx=y+dy,x+dx
     if 0<=yy<h and 0<=xx<w and test[yy][xx] and (yy,xx) not in seen: seen.add((yy,xx));q.append((yy,xx))
   objs.append((len(cells),sum(test[y][x]==9 for y,x in cells),(min(y for y,x in cells),max(y for y,x in cells),min(x for y,x in cells),max(x for y,x in cells))))
print(objs)
